css:
@page {
	size: A4 portrait;
	margin: 0;
}
* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}

body {
	font-family: "Sarabun", "TH Sarabun New", "Noto Sans Thai", sans-serif;
	font-size: 9pt;
	color: #111;
}

.page {
	background-image: url("/assets/connect_diagnostics_core/images/sales_invoice.webp");
	background-size: 210mm 297mm;
	width: 210mm;
	height: 297mm;
	position: relative;
	page-break-after: always;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	min-height: unset !important;
	max-width: unset !important;
}

